    C118780 = PermissibleValue(
        text="C118780",
        description="""\"An autosomal dominant inherited disorder caused by mutations in the TOR1A gene. It usually begins in childhood or adolescence and is characterized by involuntary muscle contractions in the arms, legs, trunk, and neck.\"""",
        meaning=HTAN["C118780"])
    C118781 = PermissibleValue(
        text="C118781",
        description="""An X-linked recessive inherited disorder caused by mutations in the MTM1 gene. Primarily it affects males. Female carriers are usually asymptomatic.  It is characterized by skeletal muscle weakness and hypotonia. The muscle weakness ranges from mild to severe. Newborns with severe X-linked centronuclear myopathy develop respiratory distress which may lead to respiratory failure requiring constant ventilator assistance. Patients with mild X-linked centronuclear myopathy usually require ventila...""",
        meaning=HTAN["C118781"])
    C118782 = PermissibleValue(
        text="C118782",
        description="""Charcot-Marie-Tooth disease caused by mutations in the MPZ gene (mapped to chromosome 1q23.3). It results in sensorineural peripheral neuropathy.""",
        meaning=HTAN["C118782"])
    C118783 = PermissibleValue(
        text="C118783",
        description="""\"An autosomal recessive inherited congenital muscular dystrophy caused by mutations in the LAMA2 gene. It is characterized by severe hypotonia, muscle weakness, elevated levels of serum creatinine kinase, and white matter abnormalities.\"""",
        meaning=HTAN["C118783"])
    C118784 = PermissibleValue(
        text="C118784",
        description="""An autosomal recessive inherited myopathy caused by mutations in the NEB gene. It is characterized by generalized hypotonia and skeletal muscle weakness.""",
        meaning=HTAN["C118784"])
    C118785 = PermissibleValue(
        text="C118785",
        description="""\"An X-linked inherited disorder caused by mutations in the GPR143 gene. It is characterized by reduced visual acuity and reduced stereoscopic vision. Other abnormalities include nystagmus, strabismus, and photophobia.\"""",
        meaning=HTAN["C118785"])
    C118786 = PermissibleValue(
        text="C118786",
        description="""\"A rare, autosomal dominant inherited syndrome caused by mutations in the IRF6 gene. It is characterized by the presence of cleft palate, cleft lip, pits in the lower lip, web behind the knee (popliteal pterygium), syndactyly, cryptorchidism, scrotal malformation, and hypoplasia of the labia majora.\"""",
        meaning=HTAN["C118786"])
    C118787 = PermissibleValue(
        text="C118787",
        description="""\"A rare, X-linked inherited syndrome caused by mutations in the GPC3 and GPC4 genes. It is characterized by pre-and postnatal overgrowth, coarse facial features, macrocephaly, macroglossia, congenital heart defects, and intellectual disability.\"""",
        meaning=HTAN["C118787"])
    C118788 = PermissibleValue(
        text="C118788",
        description="""\"A rare genetic disorder characterized by macular degeneration in the retina resulting in progressive loss of central vision with retention of the peripheral vision. It may be of early onset, autosomal dominant inherited and caused by mutations in the BEST1 gene (BEST disease) or late onset, caused by mutations in the PRPH2 gene.\"""",
        meaning=HTAN["C118788"])
