    C118829 = PermissibleValue(
        text="C118829",
        description="""A papillary or follicular thyroid gland carcinoma with a genetic component that develops within the same family. Current studies suggest that it is inherited in an autosomal dominant pattern. It is often multifocal and bilateral and usually affects younger patients.""",
        meaning=HTAN["C118829"])
    C118843 = PermissibleValue(
        text="C118843",
        description="""\"A rare, X-linked recessive inherited syndrome caused by mutations in the SLC16A2 (MCT8) gene. It affects exclusively males and is characterized by mental retardation, limited mobility, muscle hypoplasia, hypotonia, contractures, and spasticity.\"""",
        meaning=HTAN["C118843"])
    C118844 = PermissibleValue(
        text="C118844",
        description="""\"A rare disorder caused by mutations either in the IKBKG gene resulting in an X-linked recessive inheritance pattern or in the NFKBIA gene resulting in an autosomal dominant inheritance pattern. It is characterized by abnormal development of ectodermal tissues including the skin, hair, teeth, and sweat glands and immune system deficiency. It results in dry and wrinkled skin, sparse scalp and body hair, missing teeth, and reduced ability to sweat. Patients have abnormally low levels of antibo...""",
        meaning=HTAN["C118844"])
    C118845 = PermissibleValue(
        text="C118845",
        description="""\"A rare, X-linked dominant inherited syndrome caused by mutations in the FLNA gene. It is characterized by hearing loss caused by malformations in the ossicles, cleft palate, wide-set eyes, prominent brow ridges, small and flat nose, and skeletal abnormalities in the fingers and toes. Males usually experience more severe symptoms than females.\"""",
        meaning=HTAN["C118845"])
    C118846 = PermissibleValue(
        text="C118846",
        description="""\"A rare, autosomal recessive inherited skeletal muscle disorder caused by mutation in the dysferlin gene. It affects young adults and is characterized by weakness and atrophy in the muscles of the upper and lower limbs.\"""",
        meaning=HTAN["C118846"])
    C118847 = PermissibleValue(
        text="C118847",
        description="""\"A rare, autosomal recessive inherited disorder caused by mutations in the SMN1 gene. It is characterized by progressive degeneration and loss of the anterior horn cells in the spinal cord and brain stem. It is manifested with hypotonia and muscle weakness, usually in late childhood or adolescence.  Affected individuals can stand and walk but walking and climbing stairs becomes progressively difficult.\"""",
        meaning=HTAN["C118847"])
