    C119021 = PermissibleValue(
        text="C119021",
        description="An arthritis affecting fewer than five separate joints.",
        meaning=HTAN["C119021"])
    C119022 = PermissibleValue(
        text="C119022",
        description="""\"Early stages of inflammatory arthritis, when the underlying diagnosis is uncertain, usually little or no joint damage has occurred. Treatment may alter the disease course (e.g., potentially avert progression to full RA or other diagnosis).\"""",
        meaning=HTAN["C119022"])
    C119023 = PermissibleValue(
        text="C119023",
        description="""\"An inflammation of one or more joints, without loss of articular cartilage or destruction of subchondral bone.\"""",
        meaning=HTAN["C119023"])
    C119024 = PermissibleValue(
        text="C119024",
        description="""\"A category of juvenile idiopathic arthritis associated with arthritis and enthesitis, which may involve the axial skeleton. It is a form of juvenile spondyloarthritis.\"""",
        meaning=HTAN["C119024"])
    C119025 = PermissibleValue(
        text="C119025",
        description="""\"The occurrence of arthritis after infection with group A streptococcus. It is non-migratory, protracted in course, and poorly responsive to anti-inflammatory agents. (from Textbook of Pediatric Rheumatology, 6th ed. Cassidy, Petty, Laxer, and Lindsley)\"""",
        meaning=HTAN["C119025"])
    C119026 = PermissibleValue(
        text="C119026",
        description="""\"Joint inflammation, most often affecting large joints, associated with Lyme disease, presenting months after infection.\"""",
        meaning=HTAN["C119026"])
    C119031 = PermissibleValue(
        text="C119031",
        description="""\"A category of juvenile idiopathic arthritis defined by the presence of arthritis and high fevers, and accompanied by at least 2 of the following systemic features: lymphadenopathy, organomegaly, rash, or serositis. Macrophage activation syndrome is a well known complication.\"""",
        meaning=HTAN["C119031"])
    C119032 = PermissibleValue(
        text="C119032",
        description="""A category of juvenile idiopathic arthritis defined by the presence of arthritis affecting between one and four separate joints during the first six months of disease.""",
        meaning=HTAN["C119032"])
    C119033 = PermissibleValue(
        text="C119033",
        description="""\"A category of juvenile idiopathic arthritis defined by the presence of arthritis affecting five or more separate joints during the first six months of disease, with negative serologic testing for rheumatoid factor.\"""",
        meaning=HTAN["C119033"])
    C119034 = PermissibleValue(
        text="C119034",
        description="""\"A category of juvenile idiopathic arthritis defined by the presence of arthritis affecting five or more separate joints during the first six months of disease, with positive serologic testing for rheumatoid factor.\"""",
        meaning=HTAN["C119034"])
    C119035 = PermissibleValue(
        text="C119035",
        description="""A category of juvenile idiopathic arthritis that does not fulfill any single category or has criteria for more than one category.""",
        meaning=HTAN["C119035"])
    C119036 = PermissibleValue(
        text="C119036",
        description="""\"An early stage of Lyme disease that may present within 3-30 days after a tick bite with a red, concentrically-expanding rash (erythema migrans), fatigue, chills, fever, headache, muscle and joint aches, and swollen lymph nodes.\"""",
        meaning=HTAN["C119036"])
    C119037 = PermissibleValue(
        text="C119037",
        description="""\"An early stage of Lyme disease that may present days to weeks after a tick bite with relapsing signs of a red, concentrically-expanding rash (erythema migrans), facial palsy, meningismus, neuralgia, heart palpitations, and dizziness.\"""",
        meaning=HTAN["C119037"])
    C119038 = PermissibleValue(
        text="C119038",
        description="""\"A late stage of Lyme disease that may present in untreated patients months to years after a tick bite manifested with intermittent bouts of arthralgia, arthritis and neurologic complaints.\"""",
        meaning=HTAN["C119038"])
    C119039 = PermissibleValue(
        text="C119039",
        description="""A constellation of symptoms lasting months to years reported by some Lyme disease patients who had undergone previous antibiotic therapy.""",
        meaning=HTAN["C119039"])
    C119040 = PermissibleValue(
        text="C119040",
        description="""Oligoarticular juvenile idiopathic arthritis that never involves more than four separate joints after six months.""",
        meaning=HTAN["C119040"])
    C119041 = PermissibleValue(
        text="C119041",
        description="""Oligoarticular juvenile idiopathic arthritis that eventually involves more than four separate joints.""",
        meaning=HTAN["C119041"])
    C119042 = PermissibleValue(
        text="C119042",
        description="""An autoinflammatory disease characterized by sterile bone lesions which are multifocal and/or recurrent.""",
        meaning=HTAN["C119042"])
    C119043 = PermissibleValue(
        text="C119043",
        description="""An autoinflammatory disease caused by mutations in the NLRP12 gene. It is characterized by periodic fevers beginning in the first year of life that are triggered by cold exposure. Episodes occur more than once per month.""",
        meaning=HTAN["C119043"])
    C119044 = PermissibleValue(
        text="C119044",
        description="""\"A category of juvenile idiopathic arthritis defined by the presence of arthritis with a personal or family history of psoriasis, and features such as dactylitis and nail dystrophy.\"""",
        meaning=HTAN["C119044"])
    C119045 = PermissibleValue(
        text="C119045",
        description="""Recent diagnosis of rheumatoid arthritis (usually within one to two years of onset) during which treatment may be more effective and possibly improve the disease course.""",
        meaning=HTAN["C119045"])
    C119046 = PermissibleValue(
        text="C119046",
        description="Inflammation of the sclera.",
        meaning=HTAN["C119046"])
    C119048 = PermissibleValue(
        text="C119048",
        description="""\"A condition in which the nerves register normal stimuli (lack of tissue injury) as pain, resulting in feelings of intense pain with even minor sensory input.\"""",
        meaning=HTAN["C119048"])
    C119049 = PermissibleValue(
        text="C119049",
        description="""\"A syndrome characterized by synovitis, acne, pustulosis, hyperostosis, and non-infectious osteomyelitis. Includes a spectrum of aseptic neutrophilic dermatoses associated with aseptic osteoarticular lesions.\"""",
        meaning=HTAN["C119049"])
    C119050 = PermissibleValue(
        text="C119050",
        description="""A group of disorders of the innate immune system characterized by attacks of seemingly unprovoked inflammation without significant levels of either autoantibodies or autoreactive T cells more characteristic of autoimmune disease.""",
        meaning=HTAN["C119050"])
    C119051 = PermissibleValue(
        text="C119051",
        description="""\"An autoinflammatory disease caused by mutations in the TNFRSF1A gene coding for tumor necrosis factor receptor 1 (TNFR1). This results in attacks of fever, rash, peritoneal, pleural, or pericardial serositis and/or synovial inflammation along with increased acute phase reactants. Complications may include amyloidosis.\"""",
        meaning=HTAN["C119051"])
    C119053 = PermissibleValue(
        text="C119053",
        description="""\"An autoinflammatory disease caused by mutations in the NLRP3 gene which encodes cryopyrin. It is characterized by short episodes of fever, rash, and arthralgia after exposure to cold or rapid decrease in temperature.\"""",
        meaning=HTAN["C119053"])
    C119054 = PermissibleValue(
        text="C119054",
        description="""An autoinflammatory disease caused by mutations in the NLRP3 gene which encodes cryopyrin. It is characterized by recurrent episodes of urticaria and fever which develop in infancy. It may lead to sensorineural hearing loss and/or amyloidosis.""",
        meaning=HTAN["C119054"])
    C119055 = PermissibleValue(
        text="C119055",
        description="""\"An autoinflammatory disease caused by mutations in the PSTPIP1 gene. It is characterized by episodes of destructive arthritis, ulcerative skin lesions and cystic acne.\"""",
        meaning=HTAN["C119055"])
    C119056 = PermissibleValue(
        text="C119056",
        description="""\"An autoinflammatory disease caused by mutations in the IL1RN gene, which encodes the IL1 receptor antagonist. It presents in infancy, and is characterized by systemic inflammation, pustular rash, bone pain, sterile osteitis, and periostitis.\"""",
        meaning=HTAN["C119056"])
    C119057 = PermissibleValue(
        text="C119057",
        description="""\"An autoinflammatory disease caused by mutations in the IL36RN gene, which encodes the IL36 receptor antagonist. It is characterized by periodic fevers and psoriasiform rash.\"""",
        meaning=HTAN["C119057"])
    C119058 = PermissibleValue(
        text="C119058",
        description="""\"An autoinflammatory disease caused by mutations in the LPIN2 gene. It is characterized by early-onset chronic recurrent multifocal osteomyelitis, congenital dyserythropoietic anemia and inflammatory dermatosis.\"""",
        meaning=HTAN["C119058"])
    C119676 = PermissibleValue(
        text="C119676",
        description="""\"A rare, autosomal recessive inherited disorder caused by mutation in the HSD17B4 gene. It is characterized by neurodegeneration that begins in infancy, hypotonia, and seizures. The majority of the affected individuals lack developmental skills.\"""",
        meaning=HTAN["C119676"])
    C119677 = PermissibleValue(
        text="C119677",
        description="""\"A rare disorder caused by mutation in the AMACR gene. It is characterized by neurological abnormalities that appear in adulthood and include cognitive decline, seizures, and sensorimotor neuropathy.\"""",
        meaning=HTAN["C119677"])
    C119678 = PermissibleValue(
        text="C119678",
        description="""\"A rare, autosomal recessive inherited disorder caused by mutation in the TYMP gene. It affects several parts of the body, particularly the gastrointestinal tract and nervous system. Signs and symptoms can appear in infancy, but they often begin by age twenty. The gastrointestinal signs and symptoms result from gastrointestinal dysmotility and include fullness after eating small amounts of food, dysphagia, nausea and vomiting after eating, abdominal pain, diarrhea, and intestinal blockage. T...""",
        meaning=HTAN["C119678"])
    C119734 = PermissibleValue(
        text="C119734",
        description="""\"A disorder affecting the peripheral nervous system. It manifests with pain, tingling, numbness, and muscle weakness. It may be the result of physical injury, toxic substances, viral diseases, diabetes, renal failure, cancer, and drugs.\"""",
        meaning=HTAN["C119734"])
    C119751 = PermissibleValue(
        text="C119751",
        description="""Injury to the central nervous system in the newborn period that occurs when there is insufficient delivery of oxygen to all or part of the brain.""",
        meaning=HTAN["C119751"])
    C119756 = PermissibleValue(
        text="C119756",
        description="""\"A chronic lung disorder associated with pulmonary maldevelopment, scarring, and/or inflammation that develops in preterm neonates exposed to supplemental oxygen for at least 28 days. For infants born before 32 weeks gestation with mild BPD, there is no supplemental oxygen requirement at 36 weeks postmenstrual age or earlier discharge. For infants born after 32 weeks with mild BPD, there is no supplemental oxygen requirement at 56 days post-natal age or at earlier discharge.\"""",
        meaning=HTAN["C119756"])
    C119757 = PermissibleValue(
        text="C119757",
        description="""\"A chronic lung disorder associated with pulmonary maldevelopment, scarring, and/or inflammation that develops in preterm neonates exposed to supplemental oxygen for at least 28 days. For infants born before 32 weeks gestation with moderate BPD, there is a supplemental oxygen requirement of less than 30% at 36 weeks postmenstrual age or earlier discharge. For infants born after 32 weeks with moderate BPD, there is a supplemental oxygen requirement of less than 30% at 56 days post-natal age o...""",
        meaning=HTAN["C119757"])
    C119758 = PermissibleValue(
        text="C119758",
        description="""\"Abnormal functioning of the central nervous system in the newborn period that may be due to a variety of etiologies including hypoxia/ischemia, metabolic disturbance, or infection.\"""",
        meaning=HTAN["C119758"])
    C119989 = PermissibleValue(
        text="C119989",
        description="""\"Sudden onset of anterior uveitis, usually unilateral, and associated with pain, erythema, photophobia, and blurred vision. Often associated with HLA-B27, with or without co-existing spondyloarthritis.\"""",
        meaning=HTAN["C119989"])
    C119990 = PermissibleValue(
        text="C119990",
        description="""\"Lack of production of functional C1q proteins, due to a genetic defect. Virtually 100% of patients with a C1q deficiency will develop a severe systemic lupus erythematosus at an early age. Patients also present with frequent sinopulmonary infections often with Streptococcus pneumoniae.\"""",
        meaning=HTAN["C119990"])
    C119991 = PermissibleValue(
        text="C119991",
        description="""\"Lack of production of either functional C1r or C1s protein, due to a genetic defect. Approximately 60% of patients with a C1r/C1s deficiency will develop a severe systemic lupus erythematosus at an early age. Patients also present with frequent sinopulmonary infections often with Streptococcus pneumoniae.\"""",
        meaning=HTAN["C119991"])
    C119992 = PermissibleValue(
        text="C119992",
        description="""\"Lack of production of functional C2 protein, due to a genetic defect. It is the most common genetic complement deficiency. Ten percent of C2 deficient patient will develop systemic lupus erythematosus at an early age. Patients also present with frequent sinopulmonary infections often with Streptococcus pneumoniae.\"""",
        meaning=HTAN["C119992"])
    C119993 = PermissibleValue(
        text="C119993",
        description="""\"Lack of production of functional C4 protein, due to a genetic defect requiring homozygous loss of both the C4A and C4B genetic paralogs. Approximately 75% of patients with a C4 deficiency will develop a severe systemic lupus erythematosus at an early age. Patients also present with frequent sinopulmonary infections often with Streptococcus pneumoniae.\"""",
        meaning=HTAN["C119993"])
    C119996 = PermissibleValue(
        text="C119996",
        description="""The finding of one or more vertebral compression (crush) fractures in the absence of local disease or high-energy trauma or the presence of both a clinically significant fracture history and BMD Z-score less than or equal to -2.0. A clinically significant fracture history is one or more of the following: 1) two or more long bone fractures by age ten years; 2) three or more long bone fractures at any age up to age nineteen years. (from 2013 International Society for Clinical Densitometry defin...""",
        meaning=HTAN["C119996"])
    C119999 = PermissibleValue(
        text="C119999",
        description="""\"The onset of acute renal failure, normally coupled with marked hypertension in a patient with scleroderma.\"""",
        meaning=HTAN["C119999"])
    C120046 = PermissibleValue(
        text="C120046",
        description="""\"A rare genetic disorder caused by mutations in the TPM3, ACTA1, RYR1 and SEPN1 genes. It is inherited in an autosomal dominant or recessive pattern and rarely in an X-linked pattern. It manifests with myopathy throughout the body, particularly in the muscles of the shoulders, upper arms, hips, and thighs. Affected individuals may have contractures, lordosis, or scoliosis.  In a minority of cases mild to severe breathing problems may occur.\"""",
        meaning=HTAN["C120046"])
    C120069 = PermissibleValue(
        text="C120069",
        description="""\"A condition affecting premature infants characterized by white matter injury, which is frequently accompanied by neuronal/axonal disease, that may affect all brain parenchymal structures and is due to a combination of destructive processes as well as maturational and trophic disturbances.\"""",
        meaning=HTAN["C120069"])
    C120083 = PermissibleValue(
        text="C120083",
        description="""\"An inherited syndrome characterized by the development of several cancers, particularly colon and rectal cancers.  It includes Lynch syndrome which is associated with germline mutations in DNA mismatch-repair genes and familial colorectal cancer type X which is characterized by the absence of germline mutations in DNA mismatch-repair genes.\"""",
        meaning=HTAN["C120083"])
    C120084 = PermissibleValue(
        text="C120084",
        description="""Hereditary nonpolyposis colorectal cancer syndrome characterized by the absence of germline mutations in DNA mismatch-repair genes.""",
        meaning=HTAN["C120084"])
    C120113 = PermissibleValue(
        text="C120113",
        description="""A rare genetic deficiency characterized by mutations in the SHOX gene and reduced expression or function of the SHOX protein. It results in the disruption of normal bone development and growth starting before birth. It manifests with skeletal abnormalities and short stature.""",
        meaning=HTAN["C120113"])
    C120145 = PermissibleValue(
        text="C120145",
        description="Hypogonadotropic hypogonadism not associated with a deficiency of other pituitary hormones.",
        meaning=HTAN["C120145"])
