    C157781 = PermissibleValue(
        text="C157781",
        description="""\"A new infection by the hepatitis B virus, which can be transmitted by direct contact of infected blood with mucous membranes or open areas of the skin. Signs and symptoms may include loss of appetite, joint and muscle pain, low-grade fever and stomach pain. Two to six percent of adults progress to a chronic infection, while 90% of infants become chronically ill. A vaccine is available for those at risk.\"""",
        meaning=HTAN["C157781"])
    C157782 = PermissibleValue(
        text="C157782",
        description="""\"A new infection by the hepatitis C virus, which can be detected in blood. Signs and symptoms may include right upper quadrant abdominal pain, jaundice, dark urine, white stools and nausea. Approximately 15%-25% individuals clear the virus from their bodies without treatment. 75%-85% individuals develop chronic hepatitis C. There are possible treatments depending on individual characteristics.\"""",
        meaning=HTAN["C157782"])
    C157783 = PermissibleValue(
        text="C157783",
        description="""\"A new infection by the hepatitis E virus, which is usually spread by the fecal-oral route. Signs and symptoms may include fever, fatigue, loss of appetite, nausea, vomiting, abdominal pain, jaundice, dark urine, clay-colored stools and joint pain. There is no specific anti-viral treatment, the infection resolves on its own.\"""",
        meaning=HTAN["C157783"])
    C157785 = PermissibleValue(
        text="C157785",
        description="""\"A parasitic infection of the colon by Entamoeba histolytica. Signs and symptoms include cramping, diarrhea, bloody stools and fever. It can be treated with antibiotics.\"""",
        meaning=HTAN["C157785"])
