    C27723 = PermissibleValue(
        text="C27723",
        description="""\"A chronic inflammatory disorder of unknown etiology that affects the vulva. It is characterized by the development of white elevated plaques in the vulva. Histologically there is marked subepithelial fibrosis. Clinical manifestations include pruritus, dysuria, and dyspareunia.\"""",
        meaning=HTAN["C27723"])
    C27724 = PermissibleValue(
        text="C27724",
        description="""\"A chronic, sporadic, acquired pruritic non-infectious skin condition characterized by one or more well defined inflamed (pink or red) patches or plaques of varying size.\"""",
        meaning=HTAN["C27724"])
    C27725 = PermissibleValue(
        text="C27725",
        description="""\"A cutaneous form of the genetic photosensitive disease, porphyria, that is characterized by onset in adult life and the presence of scarring bullae, hyperpigmentation, facial hypertrichosis, and sometimes sclerodermatous thickenings and alopecia.  Uroporphyrins are found in the urine due to a deficiency of uroporphyrinogen decarboxylase, an enzyme required for the synthesis of heme.\"""",
        meaning=HTAN["C27725"])
    C27726 = PermissibleValue(
        text="C27726",
        description="""\"A myelodysplastic syndrome characterized by bi-cytopenia or pancytopenia, dysplastic changes in 10% or more of the cells in two or more of the myeloid cell lines, and 15% or more ring sideroblasts in the bone marrow.  (WHO, 2001)\"""",
        meaning=HTAN["C27726"])
    C27729 = PermissibleValue(
        text="C27729",
        description="""An encapsulated or well-circumscribed thyroid gland tumor composed of well-differentiated follicular cells with well-developed or partially developed nuclear features of papillary thyroid carcinoma and with questionable capsular or vascular invasion. This is a tumor indeterminate between follicular adenoma and follicular carcinoma. Tumors in which vascular invasion has been excluded by all means are called non-invasive follicular thyroid neoplasms with papillary-like nuclear features. (WHO)""",
        meaning=HTAN["C27729"])
