    C40113 = PermissibleValue(
        text="C40113",
        description="""\"A rare, benign, asymptomatic neoplasm that arises from the fallopian tube.  The majority of cases are incidental findings during operation for an unrelated gynecologic disorder.  The tumors are round and solitary and contain connective tissue and papillary or tubular structures lined by serous-type epithelium.\"""",
        meaning=HTAN["C40113"])
    C40114 = PermissibleValue(
        text="C40114",
        description="""\"A rare, benign, asymptomatic neoplasm that arises from the fallopian tube. The tumors are round and solitary and contain connective tissue and cystic structures lined by serous-type epithelium. The majority of cases are incidental findings during operation for an unrelated gynecologic disorder.\"""",
        meaning=HTAN["C40114"])
    C40115 = PermissibleValue(
        text="C40115",
        description="""An adenomatous polyp that arises from the interstitial portion of the fallopian tube and is characterized by the presence of endometrial epithelium.  It may obstruct the lumen of the fallopian tube and result in infertility or tubal pregnancy.""",
        meaning=HTAN["C40115"])
    C40116 = PermissibleValue(
        text="C40116",
        description="""\"A rare metaplastic lesion that arises from the fallopian tube. It is characterized by the presence of an intraluminal papillary proliferation composed of atypical epithelial cells with abundant eosinophilic cytoplasm. In the vast majority of cases, it is an incidental finding during microscopic examination of a fallopian tube in the postpartum period.\"""",
        meaning=HTAN["C40116"])
    C40118 = PermissibleValue(
        text="C40118",
        description="Chronic inflammation of the fallopian tube.  It usually follows an acute inflammatory attack.",
        meaning=HTAN["C40118"])
    C40119 = PermissibleValue(
        text="C40119",
        description="""Formation of nodules in the isthmus of the fallopian tube due to fallopian tube diverticulosis.  It may cause infertility or ectopic pregnancy.""",
        meaning=HTAN["C40119"])
    C4011 = PermissibleValue(
        text="C4011",
        description="A medulloblastoma occurring in adults.",
        meaning=HTAN["C4011"])
    C40120 = PermissibleValue(
        text="C40120",
        description="""\"Acute inflammation of the fallopian tube. It is most often caused by Neisseria gonorrhoeae and Chlamydia trachomatis infections. The infections usually originate in the vagina and ascend to the fallopian tube. Symptoms include abdominal, pelvic, and lower back pain, pain during ovulation and sexual intercourse, fever, nausea, and vomiting. Complications include infertility and ectopic pregnancy.\"""",
        meaning=HTAN["C40120"])
    C40124 = PermissibleValue(
        text="C40124",
        description="""\"A carcinosarcoma that arises from the fallopian tube.  It usually affects postmenopausal women and presents with abdominal pain, abdominal distension or genital bleeding.  The prognosis is usually poor.\"""",
        meaning=HTAN["C40124"])
    C40125 = PermissibleValue(
        text="C40125",
        description="""An extremely rare malignant neoplasm that arises from the fallopian tube and is characterized by the presence of a benign epithelial component and a sarcomatous component.""",
        meaning=HTAN["C40125"])
    C40126 = PermissibleValue(
        text="C40126",
        description="""A benign or malignant mesenchymal neoplasm of the fallopian tube.  Representative examples include leiomyoma and leiomyosarcoma.""",
        meaning=HTAN["C40126"])
    C40127 = PermissibleValue(
        text="C40127",
        description="""\"A benign smooth muscle neoplasm arising from the fallopian tube. It is characterized by the presence of spindle cells with cigar-shaped nuclei, interlacing fascicles, and a whorled pattern.\"""",
        meaning=HTAN["C40127"])
    C40128 = PermissibleValue(
        text="C40128",
        description="""\"An aggressive malignant smooth muscle neoplasm, arising from the fallopian tube.  It is characterized by a proliferation of neoplastic spindle cells.\"""",
        meaning=HTAN["C40128"])
    C40129 = PermissibleValue(
        text="C40129",
        description="""A benign neoplasm that arises from the fallopian tube and originates from mesothelial cells. It is characterized by the presence of gland-like structures that are lined by flat or cuboidal cells. It is usually discovered as an incidental finding.""",
        meaning=HTAN["C40129"])
    C4012 = PermissibleValue(
        text="C4012",
        description="""\"Stage IV includes: (Any T, Any N, M1a); (Any T, Any N, M1b).  M1a: Lung cancer with separate tumor nodule(s) in a contralateral lobe; tumor with pleural nodules or malignant pleural (or pericardial) effusion.  M1b: Distant metastasis. (AJCC 7th ed.)\"""",
        meaning=HTAN["C4012"])
    C40130 = PermissibleValue(
        text="C40130",
        description="""A rare germ cell tumor that affects the fallopian tube.  The vast majority of cases are teratomas.""",
        meaning=HTAN["C40130"])
    C40131 = PermissibleValue(
        text="C40131",
        description="""\"A teratoma that arises from the fallopian tube.  It is a rare tumor, often found incidentally.\"""",
        meaning=HTAN["C40131"])
    C40133 = PermissibleValue(
        text="C40133",
        description="""\"A benign, borderline, or malignant neoplasm that affects the broad or other uterine ligaments.\"""",
        meaning=HTAN["C40133"])
