    C54180 = PermissibleValue(
        text="C54180",
        description="""\"A morphologic spectrum of lesions that arise in the terminal ductal lobular units of the breast parenchyma.  These lesions are characterized by the presence of columnar epithelial cells that line dilated terminal ductal lobular units.  Cytological and architectural atypia may be absent or minimal, or significant enough to raise the possibility of atypical ductal hyperplasia or ductal carcinoma in situ.  Columnar cell lesions are frequently found in breast biopsies but their biologic signifi...""",
        meaning=HTAN["C54180"])
    C54181 = PermissibleValue(
        text="C54181",
        description="""\"A columnar cell lesion characterized by the presence of enlarged terminal ductal lobular units with dilated acini.  The acini are lined by one or two layers of columnar epithelial cells.  Apical cytoplasmic snouts may be present, but they are not prominent.  Secretions may be present in the lumina of the dilated acini.\"""",
        meaning=HTAN["C54181"])
    C54182 = PermissibleValue(
        text="C54182",
        description="""A columnar cell lesion characterized by the presence of enlarged terminal ductal lobular units with dilated acini.  The acini are lined by one or two layers of columnar epithelial cells.  Cytologic atypia is present.""",
        meaning=HTAN["C54182"])
    C54183 = PermissibleValue(
        text="C54183",
        description="""A columnar cell lesion characterized by the presence of enlarged terminal ductal lobular units with dilated acini.  The acini are lined by more than two layers of columnar epithelial cells. Prominent apical cytoplasmic snouts are present.  Secretions are often present in the lumina of the dilated acini.""",
        meaning=HTAN["C54183"])
    C54184 = PermissibleValue(
        text="C54184",
        description="""A columnar cell lesion characterized by the presence of enlarged terminal ductal lobular units with dilated acini.  The acini are lined by more than two layers of columnar epithelial cells.  Cytologic atypia is present.  Prominent apical cytoplasmic snouts and intraluminal secretions are also present.""",
        meaning=HTAN["C54184"])
