    C94328 = PermissibleValue(
        text="C94328",
        description="""\"A disorder characterized by a retrospective gap in memory of important personal information, usually of a traumatic or stressful nature; the memory loss far exceeds ordinary forgetfulness and is not the result of substance use or the consequence of a medical condition.\"""",
        meaning=HTAN["C94328"])
    C94329 = PermissibleValue(
        text="C94329",
        description="""\"A disorder characterized by sudden, unexpected travel away from one's home or place of work accompanied by an inability to recall one's past; the individual is confused about his or her personal identity and may assume a new identity.\"""",
        meaning=HTAN["C94329"])
    C94330 = PermissibleValue(
        text="C94330",
        description="""A disorder characterized by the presence of two or more identities with distinct patterns of perception and personality which recurrently take control of the person's behavior; this is accompanied by a retrospective gap in memory of important personal information that far exceeds ordinary forgetfulness. The changes in identity are not due to substance use or to a general medical condition.""",
        meaning=HTAN["C94330"])
    C94331 = PermissibleValue(
        text="C94331",
        description="""\"A disorder characterized by persistent or recurrent episodes of feeling detached from one's self (either one's body or one's mental processes), although the sufferer remains aware that this is only a feeling and does not represent reality.\"""",
        meaning=HTAN["C94331"])
    C94332 = PermissibleValue(
        text="C94332",
        description="""\"A disorder characterized by recurrent episodes of serious assaultive acts or destruction of property due to a failure to resist aggressive impulses; the degree of aggression during these episodes is grossly out of proportion to any psychosocial provocation. The aggressive episodes are not etiologically linked to another mental disorder, a general medical condition, or substance use.\"""",
        meaning=HTAN["C94332"])
    C94333 = PermissibleValue(
        text="C94333",
        description="""A disorder characterized by the recurrent failure to resist the impulse to steal items of little intrinsic value; the individual experiences a rising subjective sense of tension before the theft and a sense of gratification or relief during the theft.""",
        meaning=HTAN["C94333"])
    C94334 = PermissibleValue(
        text="C94334",
        description="""A disorder characterized by a fascination with fire and recurrent episodes of fire setting during which the individual experiences a rising subjective sense of tension before the fire setting and a sense of gratification or relief when setting the fire. There is no ulterior motive (such as monetary gain or the expression of political ideology) to the fire setting.""",
        meaning=HTAN["C94334"])
    C94335 = PermissibleValue(
        text="C94335",
        description="""\"A disorder characterized by a preoccupation with gambling and the excitement that gambling with increasing risk provides. Pathological gamblers are unable to cut back on their gambling, despite the fact that it may lead them to lie, steal, or lose a significant relationship, job, or educational opportunity.\"""",
        meaning=HTAN["C94335"])
    C94336 = PermissibleValue(
        text="C94336",
        description="""A disorder characterized by repetitive pulling out of one's hair resulting in noticeable hair loss; the individual experiences a rising subjective sense of tension before pulling out the hair and a sense of gratification or relief when pulling out the hair.""",
        meaning=HTAN["C94336"])
    C94337 = PermissibleValue(
        text="C94337",
        description="""A disorder characterized by a recurrent or persistent lack of desire for sexual activity. The lack of sexual desire is not attributable to another psychiatric disorder or to the physiological effects of substance use or a general medical condition.""",
        meaning=HTAN["C94337"])
    C94338 = PermissibleValue(
        text="C94338",
        description="""\"A disorder characterized by recurrent or persistent extreme aversion to, and avoidance of, all genital contact with a sexual partner. The aversion to sexual contact is not attributable to another psychiatric disorder.\"""",
        meaning=HTAN["C94338"])
    C94339 = PermissibleValue(
        text="C94339",
        description="""\"A disorder characterized by a recurrent or persistent inability to attain or maintain until completion of sexual activity an adequate physical response of sexual excitement, consisting of vasocongestion in the pelvis, vaginal lubrication and expansion, and swelling of the external genitalia.\"""",
        meaning=HTAN["C94339"])
    C94349 = PermissibleValue(
        text="C94349",
        description="""A disorder characterized by persistent or recurrent ejaculation before or after penetration and before the person wishes it.""",
        meaning=HTAN["C94349"])
    C94350 = PermissibleValue(
        text="C94350",
        description="""\"A disorder characterized by clinically significant sexual dysfunction (including impaired desire, impaired arousal, impaired orgasm, or sexual pain) that is fully explained by substance use.\"""",
        meaning=HTAN["C94350"])
    C94352 = PermissibleValue(
        text="C94352",
        description="""\"A disorder characterized by recurrent sexual urges, fantasies, or behaviors involving the exposure of one's genitals to an unsuspecting stranger.\"""",
        meaning=HTAN["C94352"])
