        setattr(cls, "Rivoceranib Mesylate",
            PermissibleValue(
                text="Rivoceranib Mesylate",
                description="""The mesylate salt of rivoceranib, an orally bioavailable, small-molecule receptor tyrosine kinase inhibitor with potential antiangiogenic and antineoplastic activities. Rivoceranib selectively binds to and inhibits vascular endothelial growth factor receptor 2, which may inhibit VEGF-stimulated endothelial cell migration and proliferation and decrease tumor microvessel density. In addition, this agent mildly inhibits c-Kit and c-SRC tyrosine kinases.""",
                meaning=NCIT["C74012"]))
